namespace DeyeSolar.Web.Components.Ui;
public static class ActivityPresentation
{
 public static string Kind(string value)=>value switch{"rule.checked"=>"Automation checks","rule.switched"=>"Automation switched the device","rule.created"=>"Automation created","rule.updated"=>"Automation updated","rule.deleted"=>"Automation deleted","rule.enabled"=>"Automation resumed","rule.failed"=>"Automation command failed","rule.paused"=>"Automation paused","command.manual" or "command.requested"=>"Manual switch requested","command.result"=>"Command result",_=>"Recorded activity"};
 public static string Reason(string? value)=>value switch{"Disabled" or "disabled"=>"Automation paused","SocBelowTurnOnThreshold" or "soc_below" or "soc_below_on" or "soc_below_turn_on"=>"Battery is below the switch-on threshold","RemainOn" or "soc_above" or "soc_above_off" or "soc_above_turn_off"=>"Battery is above the switch-off threshold","SolarAverageBelowThreshold" or "solar_below" or "insufficient_solar"=>"Solar average is below the threshold","Cooldown" or "cooldown"=>"Waiting between switches","OutsideActiveWindow" or "outside_window"=>"Outside the schedule window","MeasurementUnavailable" or "stale" or "stale_data"=>"Waiting for fresh readings","SolarAverageUnavailable"=>"Solar average is unavailable","TurnOn" or "TurnOnConditionsSatisfied"=>"Switch-on conditions passed","SocReachedTurnOffThreshold"=>"Battery reached the switch-off threshold","command_failed"=>"The device command failed","manual_override"=>"Paused after a manual switch","acknowledged"=>"Provider acknowledged the command","rejected"=>"Provider rejected the command","requested"=>"Command is pending","indeterminate"=>"Command result is unconfirmed","configuration_changed"=>"Configuration changed","unchanged"=>"No switch was needed","measurement_gap"=>"No readings recorded","source_changed"=>"Measurement source changed",_=>"See recorded evidence for this result"};
